.psc_group-special {
  background: #b9ddfb; 
  border:1px solid #ced4da; 
  border-color: #868e96; 
  background: var(--pt-selected-background-color); 
  border-color: var(--pt-border-contrast-color);
}

.psc_group-special .ps_box-label > .ps-label {
  color:#000;
