.ps_box-link.psc_link-drilldown > .ps-link-wrapper > .ps-link{
     display:block;
}

.ps_box-link.psc_link-drilldown{
     border: 1px solid #ced4da; 
     border-color: #868e96; 
     position:relative;
     max-width: 27.3em; 
     margin-bottom: 0.75em; 
     margin-left:0;
